        effects.append((fid, effect, t_stat, p_val, auc))

    # Sort by effect size (absolute value) and then by significance
    effects.sort(key=lambda x: abs(x[1]), reverse=True)

    # Select top features based on effect size and significance
    selected_features = []
    correlated_pairs = set()

    # Build correlation matrix
    corr_matrix = np.corrcoef(feats.x.T)

