                correlated_pairs.add((min(fid1, fid2), max(fid1, fid2)))

    # Select features while avoiding near-duplicates
    used_fids = set()
    for fid, effect, t_stat, p_val, auc in effects:
        if len(selected_features) >= MAX_DRIVERS:
            break
        # Check if this feature is correlated with any already selected
        is_correlated = False
        for sel_fid in selected_features:
            if (min(fid, sel_fid), max(fid, sel_fid)) in correlated_pairs:
                is_correlated = True
                break
        if not is_correlated and fid not in used_fids:
            selected_features.append(fid)
            used_fids.add(fid)

    # If we have strong evidence for a single driver, use it
    if len(selected_features) == 1:
        return Design(
            drivers=(selected_features[0],),
            columns=(selected_features[0],),
            products=(),
            loadings={selected_features[0]: 1.0}
        )

    # If we have two drivers, consider interaction terms
    if len(selected_features) == 2:
        return Design(
            drivers=tuple(selected_features),
            columns=tuple(selected_features),
            products=(tuple(selected_features),),
            loadings={fid: 1.0 for fid in selected_features}
        )

    # Default case: no mechanism found
    return Design(
        drivers=(),
        columns=(),
        products=(),
        loadings={}
    )

